/**
 * The docs cannot drift from the code. docs/MODEL.md's parameter tables and docs/EVAL.md's result tables are generated by
 * scripts/docs/*.ts from the constants and results themselves; these tests compare the committed docs with a fresh
 * generation. If one fails, regenerate and commit:
 *   npx tsx scripts/docs/params-table.ts --write
 *   npx tsx scripts/docs/eval-tables.ts --write
 */
import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { allEvalBlocks, illustrativeDistances, loadReport } from "../../scripts/docs/eval-tables";
import { ROOT, extractBlock } from "../../scripts/docs/blocks";
import { allParamsBlocks, undocumentedVisionExports } from "../../scripts/docs/params-table";
import { DOC_LISTS } from "../copy/banned";
import { lintText } from "../copy/lint";
import { luminanceGain } from "./castle";
import { rawDistances, type TargetSpec } from "./visibility";

const read = (file: string): string => readFileSync(`${ROOT}docs/${file}`, "utf8").replace(/\r\n/g, "\n");
const model = read("MODEL.md");
const evalDoc = read("EVAL.md");

describe("docs/MODEL.md parameter tables", () => {
  test("every export of lib/vision/params.ts is documented in a table row", () => {
    expect(undocumentedVisionExports(), "add a row for it in scripts/docs/params-table.ts").toEqual([]);
  });

  for (const [name, expected] of Object.entries(allParamsBlocks())) {
    test(`block "${name}" matches the code`, () => {
      expect(
        extractBlock(model, name),
        `docs/MODEL.md block "${name}" is stale: run npx tsx scripts/docs/params-table.ts --write`,
      ).toBe(expected.trim());
    });
  }
});

describe("docs/EVAL.md result tables", () => {
  for (const [name, expected] of Object.entries(allEvalBlocks())) {
    test(`block "${name}" matches eval/results/modelfest.json and the visibility code`, () => {
      expect(
        extractBlock(evalDoc, name),
        `docs/EVAL.md block "${name}" is stale: run npx tsx scripts/docs/eval-tables.ts --write`,
      ).toBe(expected.trim());
    });
  }

  test("the headline numbers in the prose are the ones in the results file", () => {
    const report = loadReport();
    const all = report.rmsAllDb.toFixed(2);
    const skin = report.rmsSkinDb.toFixed(2);
    expect(report.nAll).toBe(41);
    expect(report.nSkin).toBe(8);
    expect(evalDoc).toContain(`${all} dB RMS over 41`);
    expect(evalDoc).toContain(`${skin} dB over the 8`);
    expect(evalDoc).toContain(`**RMS error ${all} dB over the 41`);
    expect(evalDoc).toContain(`**RMS error ${skin} dB over the 8`);
    expect(evalDoc).toContain(`| This repository, Standard A, all analytic patterns | 41 | ${all} dB |`);
    expect(evalDoc).toContain(`| This repository, the 8 skin-relevant shapes | 8 | ${skin} dB |`);
    // Putting the two excluded patterns back at their errors on the original images gives the paper's 1.03 dB.
    const withExcluded = Math.sqrt((report.nAll * report.rmsAllDb ** 2 + 4.22 ** 2 + 2.93 ** 2) / (report.nAll + 2));
    expect(withExcluded.toFixed(2)).toBe("1.03");
  });

  test("the worked example in the prose is the first row of the distances table", () => {
    const first = illustrativeDistances()[0];
    const m = evalDoc.match(/just visible to an average observer at ([\d.]+) m, and not at all beyond ([\d.]+) m/);
    expect(m, "the 'Reading it' sentence moved or changed").not.toBeNull();
    expect(Number(m![1])).toBe(Number(first.nominalM.toFixed(1)));
    expect(Number(m![2])).toBe(Number(first.boundM.toFixed(1)));
  });
});

describe("numbers quoted in the prose of docs/MODEL.md", () => {
  test("3 mm, 12% disk: 3.2 m at 0 dB, 4.8 m at 6 dB, about 5.9 m at 9 dB", () => {
    const spec: TargetSpec = { id: "x", concern: "age_spot", shape: "disk", sizeMm: 3, lum: -0.12, rg: 0, yv: 0, chromatic: false };
    const at = (marginDb: number) =>
      rawDistances(spec, { luminanceCdM2: 30, acuityScale: 1, label: "custom", marginDb }).bound.toFixed(1);
    expect([at(0), at(6), at(9)]).toEqual(["3.2", "4.8", "5.9"]);
    expect(model).toContain("the distance is 3.2 m at 0 dB, 4.8 m at 6 dB and about 5.9 m at 9 dB");
  });

  test("luminance factor at 4 cycles/deg for 3, 10, 30, 100, 300, 1000 cd/m^2", () => {
    const g = [3, 10, 30, 100, 300, 1000].map((L) => luminanceGain(L, 4).toFixed(2));
    expect(g.join(", ")).toBe("0.45, 0.73, 1.00, 1.22, 1.33, 1.38");
    expect(model).toContain(`it is ${g.join(", ")} at\n3, 10, 30, 100, 300, 1000 cd/m^2`);
  });
});

describe("docs pass the copy linter", () => {
  for (const [file, text] of [
    ["docs/MODEL.md", model],
    ["docs/EVAL.md", evalDoc],
  ] as const) {
    test(`${file} has no medical, shaming or trademark words`, () => {
      expect(lintText(text, DOC_LISTS).map((v) => `${v.list}: "${v.word}" at ${v.index}`)).toEqual([]);
    });
  }
});
